.dottedstyle .vertical-dotted-line {
  position: absolute;
  left: 0.4375rem;
  bottom: 0;
  top: 1.5rem;
  width: 0.1875rem;
  height: 100%;
  border-right: 1px dashed;
}
.dottedstyle .horizontal-dotted-line {
  height: 0.375rem;
  width: 1.15rem;
  border-bottom: 1px dashed;
  position: relative;
  right: 1.15rem;
}
.dottedstyle .node-dot {
  border-radius: 50%;
  height: 0.75rem;
  width: 0.75rem;
  margin-right: 0.5625px;
  margin-left: 0.1875rem;
  margin-top: 0.3125rem;
}
.dottedstyle .node-label {
  font-size: 0.875rem;
  font-weight: 400;
  margin-left: 0.625rem;
  cursor: pointer;
}
.dottedstyle .node {
  margin-top: 0.625rem;
}
.dottedstyle .node-count {
  padding-left: 1.5rem;
  font-size: 0.765625rem;
}
.dottedstyle .nest-icon {
  animation: fadeInAnimation ease 0.3s;
}
@keyframes fadeInAnimation {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 0;
  }
}

.vertical-dotted-line-select-all {
  position: absolute;
  bottom: 0;
  top: 1.25rem;
  width: 0.5625rem;
  height: 100.2%;
  border-right: 1px dashed;
}

.checkedstyle .vertical-dotted-line {
  position: absolute;
  left: 0rem;
  bottom: 0;
  top: 2rem;
  width: 0.5625rem;
  height: 100%;
  border-right: 1px dashed;
}
.checkedstyle .horizontal-dotted-line {
  height: 0.25rem;
  width: 1rem;
  border-bottom: 1px dashed;
  position: relative;
  right: 1rem;
  margin-top: -1.095rem;
}
.checkedstyle .node-dot {
  border-radius: 50%;
  height: 0.4374rem;
  width: 0.375rem;
  margin-right: 0.9375rem;
}
.checkedstyle .node-label {
  font-weight: 400;
  margin-top: 0.8875rem;
  margin-left: 0.2rem;
}
.checkedstyle .node-label:active {
  font-weight: 400;
}
.checkedstyle .nest-icon {
  animation: fadeInAnimation ease 0.3s;
}
@keyframes fadeInAnimation {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}

