  background: radial-gradient(10.08px at bottom right, rgba(0, 0, 0, 0) 94%, currentColor) top left, radial-gradient(10.08px at bottom left, rgba(0, 0, 0, 0) 94%, currentColor) top right, radial-gradient(10.08px at top right, rgba(0, 0, 0, 0) 94%, currentColor) bottom left, radial-gradient(10.08px at top left, rgba(0, 0, 0, 0) 94%, currentColor) bottom right;
  background-size: 22.4px 22.4px;
  background-repeat: no-repeat;
  animation: loader 1.5s infinite cubic-bezier(0.3, 1, 0, 1);
}

@keyframes loader {
  33% {
    inset: -11.2px;
    transform: rotate(0deg);
  }
  66% {
    inset: -11.2px;
    transform: rotate(90deg);
  }
  100% {
    inset: 0;
    transform: rotate(90deg);
  }
}
.rotate, .rotate::before, .rotate::after {
  border-width: 2px;
  border-style: solid;
  border-radius: 10px;
  animation: rotate 5s linear infinite;
}

.rotate {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: 40px;
  height: 40px;
  border-color: #5a4ff3;
}

.rotate::before, .rotate::after {
  position: absolute;
  content: "";
}

.rotate::before {
  border-color: #35a2d2;
  width: 110%;
  height: 110%;
  animation-delay: 0.5s;
}

.rotate::after {
  border-color: #9c40fc;
  width: 120%;
  height: 120%;
  animation-delay: 0.1s;
}

@keyframes rotate {
  to {
    transform: rotate(360deg);
  }
}
.spin {
  width: 56px;
  height: 56px;
  display: grid;
  border: 4px solid rgba(0, 0, 0, 0);
  border-radius: 50%;
  border-right-color: #004dff;
  animation: spinner-a4dj62 1s infinite linear;
}

.spin::before,
.spin::after {
  content: "";
  grid-area: 1/1;
  margin: 2px;
  border: inherit;
  border-radius: 50%;
  animation: spinner-a4dj62 2s infinite;
}

.spin::after {
  margin: 8px;
  animation-duration: 3s;
}

@keyframes spinner-a4dj62 {
  100% {
    transform: rotate(1turn);
  }
}
.triangle {
  width: 50px;
  aspect-ratio: 1.154;
  position: relative;
  background: conic-gradient(from 120deg at 50% 64%, rgba(0, 0, 0, 0), #ff1919 1deg 120deg, rgba(0, 0, 0, 0) 121deg);
  animation: l27-0 1.5s infinite cubic-bezier(0.3, 1, 0, 1);
}

.triangle:before,
.triangle:after {
  content: "";
  position: absolute;
  inset: 0;
  background: inherit;
  transform-origin: 50% 66%;
  animation: l27-1 1.5s infinite;
}

.triangle:after {
  --s: -1;
}

@keyframes l27-0 {
  0%, 30% {
    transform: rotate(0);
  }
  70% {
    transform: rotate(120deg);
  }
  70.01%, 100% {
    transform: rotate(360deg);
  }
}
@keyframes l27-1 {
  0% {
    transform: rotate(calc(var(--s, 1) * 120deg)) translate(0);
  }
  30%, 70% {
    transform: rotate(calc(var(--s, 1) * 120deg)) translate(calc(var(--s, 1) * -5px), 10px);
  }
  100% {
    transform: rotate(calc(var(--s, 1) * 120deg)) translate(0);
  }
}
.spinner-ring {
  --spinner-ring-size: 120px;
  --spinner-ring-border-main: 8px;
  --spinner-ring-border-pseudo: 3px;
  width: var(--spinner-ring-size);
  height: var(--spinner-ring-size);
  border: var(--spinner-ring-border-main) solid transparent;
  border-top: var(--spinner-ring-border-main) solid #6c2bd9;
  border-right: var(--spinner-ring-border-main) solid #6c2bd9;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
}
.spinner-ring.loader-medium {
  --spinner-ring-size: 80px;
  --spinner-ring-border-main: 5px;
  --spinner-ring-border-pseudo: 2px;
}
.spinner-ring.loader-small {
  --spinner-ring-size: 40px;
  --spinner-ring-border-main: 3px;
  --spinner-ring-border-pseudo: 1px;
}
.spinner-ring::before, .spinner-ring::after {
  content: "";
  position: absolute;
  border: var(--spinner-ring-border-pseudo) solid #6c2bd9;
  border-radius: 50%;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  box-sizing: border-box;
}
.spinner-ring::before {
  width: 131%;
  height: 131%;
  border-color: #6c2bd9;
}
.spinner-ring::after {
  width: 88%;
  height: 88%;
  border-color: #6c2bd9;
}

@keyframes spin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
.progress-circle {
  width: 100%;
  height: 100%;
  border-radius: 50%; /* Default border-radius */
  position: relative;
}

.progress-circle-inner {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 85%;
  height: 85%;
  border-radius: 50%;
  background-color: white;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.progress-percentage {
  font-size: 0.75rem;
  font-weight: 400;
}

